    const [editManoObra, setEditManoObra] = useState("");
    const [editMaterials, setEditMaterials] = useState<{ material: string; piezas: string; precio: string }[]>([]);
    const [editCosto, setEditCosto] = useState("");
    const [editNotas, setEditNotas] = useState("");
    const [editArchivoFile, setEditArchivoFile] = useState<File | null>(null);
    const [editNombreArchivo, setEditNombreArchivo] = useState("");
    const editFileInputRef = useRef<HTMLInputElement>(null);
    const [tecnicosData, setTecnicosData] = useState<Tecnico[]>([]);
    const [showAddQuoteForm, setShowAddQuoteForm] = useState(false);

    // ESTADOS RECHAZO CON MOTIVO
    const [showRejectionModal, setShowRejectionModal] = useState(false);
    const [rejectionReason, setRejectionReason] = useState("");
    const [quoteToReject, setQuoteToReject] = useState<number | null>(null);

    useEffect(() => {
        const fetchTecnicos = async () => {
            try {
                const data = await getTrabajadores();
                // Filtramos activos si es que hay un campo estado activo (opcional) o tomamos todos
                const techList = data.filter((t: any) => t.estado?.toLowerCase() === 'activo' || t.estado === 'Activo');
                setTecnicosData(techList.map((t: any) => ({
                    id: t.id,
                    nombre: t.nombre,
                    user_id: t.user_id ?? t.userId ?? null
                })));
            } catch (error) {
                console.error("Error al obtener técnicos:", error);
            }
        };
        fetchTecnicos();
    }, []);

    useEffect(() => {
        const fetchAll = async () => {
            if (!id) return;
            let currentTech = "Admin/Técnico";
            try {
                const data = await getTrabajo(Number(id));
                currentTech = data.trabajador?.nombre || "Sin Asignar";
                const isEmergencyJob = Boolean(
                    data.tipo === "SOS" ||
                    data.prioridad === "Emergencia" ||
                    data.is_emergency ||
                    data.isEmergency ||
                    (data.titulo || "").toUpperCase().includes("SOS") ||
                    (data.titulo || "").toUpperCase().includes("EMERGENCIA") ||
                    (data as any)?.solicitud?.tipo === "SOS" ||
                    (data as any)?.solicitud?.prioridad === "Emergencia" ||
                    (data as any)?.solicitud?.is_emergency ||
                    data.tipo_servicio === "SOS" ||
                    data.servicio === "SOS" ||
                    data.categoria === "SOS" ||
                    data.originalTipo === "SOS"
                );

                const calculatedTipo = (() => {
                    if (isEmergencyJob) return "SOS";
                    if (data.tipo === "SOS") return "SOS";
                    if (data.tipo === "Trabajo") return "Trabajo";
                    if (data.tipo === "Visita") {
                        if (["Cotización Aceptada", "Cotización Aprobada", "En Ejecución", "Finalizado"].includes(data.estado)) {
                            return "Trabajo";
                        }
                        return "Visita";
                    }
                    return (["Cotización Aceptada", "Cotización Aprobada", "En Ejecución", "Finalizado"].includes(data.estado)) ? "Trabajo" : (data.tipo || "Visita");
                })();

                const mappedJob = {
                    id: data.id,
                    titulo: data.titulo || (data as any).descripcion?.substring(0, 20) || "Servicio",
                    ubicacion: data.negocio?.ubicacion || "Por definir",
                    tecnico: currentTech,
                    fecha: data.fecha_programada || new Date(data.created_at).toLocaleDateString('es-MX'),
                    estado: (data.estado === "Pendiente" ? "Solicitud" : data.estado) as any,
                    tipo: calculatedTipo,
                    originalTipo: data.tipo || data.originalTipo || calculatedTipo,
                    prioridad: data.prioridad || (isEmergencyJob ? "Emergencia" : ""),
                    isEmergency: isEmergencyJob,
                    tipo_servicio: data.tipo_servicio || data.servicio || "",
                    servicio: data.servicio || data.tipo_servicio || "",
                    categoria: data.categoria || "",
                    solicitud: (data as any).solicitud || null,
                    visitado: data.visitado,
                    descripcion: data.descripcion,
                    latitud_llegada: data.latitud_llegada,
                    longitud_llegada: data.longitud_llegada,
                    hora_llegada: data.hora_llegada,
                    sucursal: data.negocio?.nombre || "Por definir",
                    encargado: data.negocio?.encargado || "No registrado",
                    telefonoEncargado: data.negocio?.telefono || data.negocio?.telefonoEncargado || "S/N",
                    subgerente: data.negocio?.subgerente || "No registrado",
                    telefonoSubgerente: data.negocio?.telefonoSubgerente || "S/N",
                    plaza: data.negocio?.nombrePlaza || data.negocio?.nombre_plaza || "Por definir",
                    ciudad: data.negocio?.ciudad || "Mérida",
                    calle: data.negocio?.calle || "Por definir",
                    numero: data.negocio?.numero || "S/N",
                    colonia: data.negocio?.colonia || "Por definir",
                    cp: data.negocio?.cp || "S/N",
                    manzana: data.negocio?.manzana || "Por definir",
                    lote: data.negocio?.lote || "Por definir",
                    referencias: data.negocio?.referencias || "Por definir",
                    fechaSolicitud: data.created_at
                        ? new Date(data.created_at).toLocaleString('es-MX', { day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit', hour12: true })
                        : "No registrada",
                    fecha_programada: data.fecha_programada || null,
                    horaAsignada: data.horaAsignada ? (data.horaAsignada.length > 5 ? data.horaAsignada.substring(0, 5) : data.horaAsignada) : (data.hora_asignada ? (data.hora_asignada.length > 5 ? data.hora_asignada.substring(0, 5) : data.hora_asignada) : (data.hora_programada || null)),
                    hora_programada: data.horaAsignada ? (data.horaAsignada.length > 5 ? data.horaAsignada.substring(0, 5) : data.horaAsignada) : (data.hora_programada || data.hora_asignada || null),
                    businessId: data.negocio_id || data.negocio?.id,
                    negocio_id: data.negocio_id || data.negocio?.id,
                    admin_autonomo_id: data.admin_autonomo_id || data.negocio?.admin_autonomo_id,
                    clienteUserId: data.negocio?.user_id || null,
                    clienteNombre: data.negocio?.user?.name || "",
                    clienteEmail: data.negocio?.user?.email || "",
                    clienteTelefono: data.negocio?.user?.telefono || "",
                    foto_url: data.foto_url || null,
                    trabajador_id: data.trabajador_id || data.trabajador?.id || null,
                    trabajador: data.trabajador || null,
                    tecnicoUserId: data.trabajador?.user_id || null
                };

                // Autofill Marca and Modelo if there is a linked MantenimientoSolicitud
                const solicitud = data.mantenimiento_solicitud_visita || data.mantenimientoSolicitudVisita || data.mantenimiento_solicitud_reparacion || data.mantenimientoSolicitudReparacion;
                const equipo = solicitud ? (solicitud.levantamiento_equipo || solicitud.levantamientoEquipo) : null;

                if (equipo) {
                    setServiceMarca(equipo.marca || equipo.nombre || "");
                    setServiceModelo(equipo.modelo || "");
                    setServiceEquipoId(equipo.id);
                } else if (data.descripcion && typeof data.descripcion === 'string' && data.descripcion.includes('[Equipo:')) {
                    const match = data.descripcion.match(/\[Equipo:\s*(.+?)\]/);
                    if (match && match[1]) {
                        const equipoNombre = match[1].trim();
                        let cleanName = equipoNombre.replace(/\(.*?\)/g, '').trim();
                        let parts = cleanName.split(' ');
                        if (parts.length >= 3) {
                            setServiceMarca([parts[0], parts[1]].join(' '));
                            setServiceModelo(parts.slice(2).join(' '));
                        } else {
                            setServiceMarca(equipoNombre);
                        }
                    }
                }

                // FETCH REPORTE FINAL DESDE DB
                try {
                    const dbReport = await getReporteByTrabajoId(Number(id));
                    if (dbReport && dbReport.solucion) {
                        if (dbReport.solucion.trim().startsWith('{')) {
                            try {
                                const parsed = JSON.parse(dbReport.solucion);
                                setReporteFinal({ ...parsed, dbId: dbReport.id });
                                localStorage.setItem(`report_data_${id}`, dbReport.solucion);
                                if (parsed.subtareaId) {
                                    localStorage.setItem(`report_data_${parsed.subtareaId}`, JSON.stringify(parsed));
                                }
                                if (parsed.subReports && typeof parsed.subReports === 'object') {
                                    Object.entries(parsed.subReports).forEach(([subKey, subData]) => {
                                        try {
                                            localStorage.setItem(`report_data_${subKey}`, JSON.stringify(subData));
                                            if (subKey.includes('_')) {
                                                const ptNum = subKey.split('_')[1];
                                                localStorage.setItem(`report_data_${id}_${ptNum}`, JSON.stringify(subData));
                                            }
                                        } catch (_) { }
                                    });
                                }
                            } catch (e) {
                                console.error("Error parsing report JSON:", e);
                            }
                        }
                    }
                } catch (reportErr) {
                    console.error("Error fetching report from DB:", reportErr);
                }

                // FETCH CHATS TO CHECK FOR LATEST QUOTE
                try {
                    const token = localStorage.getItem('token');
                    if (token) {
                        const API_URL = import.meta.env.VITE_API_URL || 'http://127.0.0.1:8085/api';
                        const chatRes = await fetch(`${API_URL}/trabajos/${id}/chat`, {
                            headers: { 'Authorization': `Bearer ${token}` }
                        });
                        if (chatRes.ok) {
                            const chatData = await chatRes.json();
                            const lastQuote = chatData.reverse().find((msg: any) => msg.is_quote);
                            if (lastQuote) {
                                setLatestChatQuote(lastQuote);
                            }
                        }
                    }
                } catch (chatErr) {
                    console.error("Error fetching chats for quote check:", chatErr);
                }

                // FETCH GROUPED JOBS IF APPLICABLE
                const groupMatch = mappedJob.descripcion?.match(/\[Grupo:\s*(REQ-\d+)\]/);
                const groupId = groupMatch ? groupMatch[1] : null;

                let groupJobsList: any[] = [];
                if (groupId && mappedJob.negocio_id) {
                    try {
                        const allJobs = await getTrabajos({ negocio_id: Number(mappedJob.negocio_id) });
                        groupJobsList = allJobs.filter((t: any) => t.descripcion?.includes(`[Grupo: ${groupId}]`));
                        // Ordenar de menor a mayor por ID
                        groupJobsList.sort((a: any, b: any) => Number(a.id) - Number(b.id));
                        setGroupedJobs(groupJobsList);
                    } catch (err) {
                        console.error("Error fetching grouped jobs:", err);
                        setGroupedJobs([]);
                    }
                } else {
                    setGroupedJobs([]);
                }

                // RECOLECTAR EQUIPOS EXCLUSIVOS DEL MANTENIMIENTO
                const equipMap = new Map<string, { id: number | string; nombre: string; marca: string; modelo: string; area?: string }>();
                const addEquip = (eq: any) => {
                    if (!eq) return;
                    const key = `${eq.id || ''}_${eq.nombre || ''}_${eq.marca || ''}_${eq.modelo || ''}`;
                    if (!equipMap.has(key)) {
                        equipMap.set(key, {
                            id: eq.id || key,
                            nombre: eq.nombre || eq.name || 'Equipo',
                            marca: eq.marca || eq.nombre || '',
                            modelo: eq.modelo || '',
                            area: eq.area || eq.levantamientoArea?.nombre || eq.levantamiento_area?.nombre || ''
                        });
                    }
                };

                // 1. Del trabajo actual
                if (equipo) {
                    addEquip(equipo);
                } else if (data.levantamiento_equipo || data.levantamientoEquipo) {
                    addEquip(data.levantamiento_equipo || data.levantamientoEquipo);
                }

                // 2. De los trabajos agrupados en la misma solicitud
                if (groupJobsList && groupJobsList.length > 0) {
                    groupJobsList.forEach((gj: any) => {
                        const gjSol = gj.mantenimiento_solicitud_visita || gj.mantenimientoSolicitudVisita || gj.mantenimiento_solicitud_reparacion || gj.mantenimientoSolicitudReparacion;
                        if (gjSol?.levantamiento_equipo || gjSol?.levantamientoEquipo) {
                            addEquip(gjSol.levantamiento_equipo || gjSol.levantamientoEquipo);
                        } else if (gj.levantamiento_equipo || gj.levantamientoEquipo) {
                            addEquip(gj.levantamiento_equipo || gj.levantamientoEquipo);
                        } else if (gj.descripcion && gj.descripcion.includes('[Equipo:')) {
                            const m = gj.descripcion.match(/\[Equipo:\s*(.+?)\]/);
                            if (m && m[1]) {
                                addEquip({ id: `g_${gj.id}`, nombre: m[1].trim(), marca: m[1].trim(), modelo: '' });
                            }
                        }
                    });
                }

                // 3. Fallback de descripción / título
                if (equipMap.size === 0 && data.descripcion && typeof data.descripcion === 'string' && data.descripcion.includes('[Equipo:')) {
                    const match = data.descripcion.match(/\[Equipo:\s*(.+?)\]/);
                    if (match && match[1]) {
                        addEquip({ id: 'desc_eq', nombre: match[1].trim(), marca: match[1].trim(), modelo: '' });
                    }
                }
                if (equipMap.size === 0 && data.titulo) {
                    const tMatch = data.titulo.match(/Mantenimiento\s*(?:\([^)]+\))?:\s*([^(]+)/i);
                    if (tMatch && tMatch[1]) {
                        addEquip({ id: 'title_eq', nombre: tMatch[1].trim(), marca: tMatch[1].trim(), modelo: '' });
                    }
                }

                const listEquips = Array.from(equipMap.values());
                setMaintenanceEquipmentList(listEquips);

                if (listEquips.length > 0) {
                    const firstEq = listEquips[0];
                    setServiceMarca(firstEq.marca || firstEq.nombre || "");
                    setServiceModelo(firstEq.modelo || "");
                    setServiceEquipoId(typeof firstEq.id === 'number' ? firstEq.id : null);

                    // Auto-llenar el Punto 1 si está vacío
                    setTaskItems(prev => prev.map((item, idx) => {
                        if (idx === 0 && (!item.marca || item.marca === '')) {
                            return {
                                ...item,
                                selectedEquipId: String(firstEq.id),
                                marca: firstEq.marca || firstEq.nombre || '',
                                modelo: firstEq.modelo || ''
                            };
                        }
                        return item;
                    }));
                }

                // Si el trabajo quedó marcado como 'Cotización Aceptada' pero no tiene cotizaciones guardadas o aprobadas por cliente, restaurar a 'En Espera'
                if (mappedJob && (mappedJob.estado === 'Cotización Aceptada' || mappedJob.estado === 'Cotización Aprobada')) {
                    try {
                        const existingCotiz = await getCotizaciones(Number(id));
                        const hasApprovedCotiz = Array.isArray(existingCotiz) && existingCotiz.some((c: any) => c.estado === 'Aprobada');
                        if (!hasApprovedCotiz && (!existingCotiz || existingCotiz.length === 0)) {
                            mappedJob.estado = 'En Espera';
                            updateEstadoTrabajo(Number(id), { estado: 'En Espera' }).catch(() => {});
                        }
                    } catch (_) {}
                }

                setTrabajo(mappedJob as any);

                // Ajuste inteligente de pestaña según el estado del trabajo y rol
                const isJobSOS = Boolean(mappedJob.tipo === "SOS" || mappedJob.prioridad === "Emergencia" || (mappedJob.titulo || '').includes("SOS") || (mappedJob as any)?.isEmergency);

                if (!rawTabParam) {
                    if (mappedJob.estado === 'Rechazada') {
                        setActiveTab('Datos');
                    } else if (isAutonomoAdminUser) {
                        setActiveTab(prev => prev === 'Trabajo' ? 'Datos' : prev);
                    } else if (isJobSOS) {
                        // En emergencias SOS:
                        if (['Cotización Aceptada', 'Cotización Aprobada', 'En Ejecución', 'Finalizado'].includes(mappedJob.estado) && isTechRole) {
                            setActiveTab('Trabajo');
                        } else if (mappedJob.estado === 'Cotización Enviada' || (mappedJob.visitado && !['Cotización Aceptada', 'Cotización Aprobada', 'En Ejecución', 'Finalizado'].includes(mappedJob.estado))) {
                            setActiveTab('Cotización');
                        } else if (['Asignado', 'En Espera', 'En Proceso'].includes(mappedJob.estado) && isTechRole && !mappedJob.visitado) {
                            setActiveTab('Registro');
                        } else {
                            // Si está en Solicitud o Pendiente, ver 'Datos' para revisar
                            setActiveTab('Datos');
                        }
                    } else if (mappedJob.tipo === 'Visita') {
                        if (!mappedJob.visitado || mappedJob.estado === 'Recotización Solicitada' || mappedJob.estado?.toLowerCase().includes('recotiz')) {
                            setActiveTab('Registro');
                        } else if (['Cotización Aceptada', 'Cotización Aprobada', 'En Ejecución'].includes(mappedJob.estado) && isTechRole) {
                            setActiveTab('Trabajo');
                        } else {
                            setActiveTab('Datos');
                        }
                    } else if (mappedJob.tipo === 'Trabajo') {
                        if (['Cotización Aceptada', 'Cotización Aprobada', 'En Ejecución', 'En Proceso'].includes(mappedJob.estado) && isTechRole) {
                            setActiveTab('Trabajo');
                        } else {
                            setActiveTab('Datos');
                        }
                    } else {
                        setActiveTab('Datos');
                    }
                }

                // En SOS, el Administrador debe ver la pestaña 'Datos' hasta que el técnico envíe su cotización
                if (isJobSOS && isAdminUser && (mappedJob.estado === 'Solicitud' || mappedJob.estado === 'Pendiente' || mappedJob.estado === 'Asignado' || mappedJob.estado === 'En Espera')) {
                    setActiveTab(prev => prev === 'Cotización' ? 'Datos' : prev);
                }

            } catch (error) {
                console.error("No se pudo hallar el trabajo en servidor:", error);
                setTrabajo(null);
            }
        };

        if (id) {
            fetchAll();
        }

        const handleStorageChange = (e: StorageEvent) => {
            if (e.key === `trabajo_updated_${id}`) {
                fetchAll();
            }
        };
        window.addEventListener('storage', handleStorageChange);
        return () => {
            window.removeEventListener('storage', handleStorageChange);
        };
    }, [id]);

    // Evitar cualquier desfase o "cruce de datos": si la pestaña activa no corresponde al estado actual de SOS o al rol
    useEffect(() => {
        if (!trabajo) return;

        // En SOS: si la cotización aún NO ha sido aceptada/aprobada, 'Trabajo' NO debe estar activa bajo ninguna circunstancia
        if (isSOS && activeTab === 'Trabajo' && !['Cotización Aceptada', 'Cotización Aprobada', 'En Ejecución', 'Finalizado'].includes(trabajo.estado)) {
            setActiveTab(!trabajo.visitado && isTechRole ? 'Registro' : (trabajo.estado === 'Cotización Enviada' && isTechRole ? 'Cotización' : 'Datos'));
        }

        // Si el admin autónomo tiene 'Trabajo' activo
        if (isAutonomoAdminUser && activeTab === 'Trabajo') {
            setActiveTab('Datos');
        }
    }, [trabajo?.estado, isSOS, activeTab, isTechRole, isAutonomoAdminUser]);

    const handleQuoteAction = async (action: 'accept' | 'reject', reason?: string) => {
        try {
            const token = localStorage.getItem('token');
            if (!token) return;

            const API_URL = import.meta.env.VITE_API_URL || 'http://127.0.0.1:8085/api';
            const res = await fetch(`${API_URL}/trabajos/${id}/quote-action`, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    'Authorization': `Bearer ${token}`
                },
                body: JSON.stringify({ action, reason })
            });

            if (res.ok) {
                const data = await res.json();
                setTrabajo(data.trabajo);
                setLatestChatQuote(null); // Clear the quote notification
                setShowRejectionModal(false);
                setRejectionReason("");

                // If accepted, maybe switch tab to Trabajo
                if (action === 'accept') {
                    setActiveTab('Trabajo');
                }
            } else {
                console.error("Error updating quote action");
            }
        } catch (error) {
            console.error("Error:", error);
        }
    };

    useEffect(() => {
        const fetchActividades = async () => {
            if (!id) return;
            try {
                const acts = await getActividadesByTrabajo(Number(id));
                const mappedSubTareas = acts.map((act: any) => {
                    let finalDesc = act.descripcion || "";
                    let parsedMonto = "Por Evaluar";
                    let sData = null;
                    let qData = null;

                    const quoteMarker = "|||QUOTE_DATA|||";
                    const serviceMarker = "|||SERVICE_DATA|||";
                    const techMarker = "|||TECH_NAME|||";
                    const photosMarker = "|||PHOTOS_DATA|||";

                    let authorName = (trabajo?.tecnico && trabajo.tecnico !== "Sin Asignar") ? trabajo.tecnico : (user?.name || "Sin Asignar");
                    if (finalDesc.includes(techMarker)) {
                        const tParts = finalDesc.split(techMarker);
                        try {
                            authorName = tParts[1].split('\n')[0].split('|||')[0].trim();
                        } catch (e) { }
                    }

                    // Limpiamos la descripción mostrada de todos los marcadores técnicos
                    const cleanDesc = finalDesc
                        .split(serviceMarker)[0]
                        .split(quoteMarker)[0]
                        .split(techMarker)[0]
                        .split(photosMarker)[0]
                        .trim();

                    let displayDesc = cleanDesc;

                    if (finalDesc.includes(serviceMarker)) {
                        const parts = finalDesc.split(serviceMarker);
                        try {
                            // Limpiamos cualquier marcador que venga después del JSON del servicio
                            const jsonContent = parts[1].split(quoteMarker)[0].split(techMarker)[0].split(photosMarker)[0].trim();
                            sData = JSON.parse(jsonContent);
                        } catch (e) {
                        }
                    }

                    if (finalDesc.includes(quoteMarker)) {
                        const parts = finalDesc.split(quoteMarker);
                        try {
                            // Limpiamos cualquier marcador que venga después del JSON de la cotización
                            const jsonContent = parts[1].split(serviceMarker)[0].split(techMarker)[0].split(photosMarker)[0].trim();
                            if (jsonContent.startsWith('{')) {
                                qData = JSON.parse(jsonContent);
                                // New format: {conceptos, materiales, comentarios}
                                if (qData.conceptos || qData.materiales) {
                                    let totalMonto = 0;
                                    if (qData.conceptos) {
                                        for (const c of qData.conceptos) {
                                            totalMonto += (Number(c.cantidad) || 1) * (Number(c.precio) || 0);
                                        }
                                    }
                                    if (qData.materiales) {
                                        for (const m of qData.materiales) {
                                            totalMonto += (Number(m.cantidad) || 1) * (Number(m.precio) || 0);
                                        }
                                    }
                                    if (totalMonto > 0) parsedMonto = totalMonto.toString();
                                    if (qData.comentarios) displayDesc += "\n\nNotas de cotización:\n" + qData.comentarios;
                                } else {
                                    // Legacy format: {monto, detalles}
                                    if (qData.monto) parsedMonto = qData.monto;
                                    if (qData.detalles) displayDesc += "\n\nNotas de cotización:\n" + qData.detalles;
                                }
                            } else {
                                // Plain text fallback
                                const firstHyphen = jsonContent.indexOf(" - ");
                                if (firstHyphen !== -1) {
                                    const possibleMonto = jsonContent.substring(0, firstHyphen).trim();
                                    if (!isNaN(Number(possibleMonto.replace('$', '')))) {
                                        parsedMonto = possibleMonto;
                                        const detailsText = jsonContent.substring(firstHyphen + 3).trim();
                                        qData = { monto: possibleMonto, detalles: detailsText };
                                    } else {
                                        qData = { monto: "", detalles: jsonContent };
                                    }
                                } else {
                                    qData = { monto: "", detalles: jsonContent };
                                }
                                if (qData.detalles) displayDesc += "\n\nNotas de cotización:\n" + qData.detalles;
                            }
                        } catch (e) { }
                    }

                    let photosList: string[] = [];
                    if (finalDesc.includes(photosMarker)) {
                        const parts = finalDesc.split(photosMarker);
                        try {
                            const jsonContent = parts[1].split(serviceMarker)[0].split(quoteMarker)[0].split(techMarker)[0].trim();
                            photosList = JSON.parse(jsonContent);
                        } catch (e) { }
                    }

                    // Build refacciones from QUOTE_DATA if DB refacciones are empty
                    let finalRefacciones = act.refacciones && act.refacciones.length > 0 ? act.refacciones : [];

                    // Deduplicate corrupted DB data: remove items that exist in quoteData
                    if (finalRefacciones.length > 0 && qData) {
                        const qConceptNames = (qData.conceptos || []).map((c: any) => c.descripcion?.trim().toLowerCase());
                        const qMaterialNames = (qData.materiales || []).map((m: any) => m.nombre?.trim().toLowerCase());

                        finalRefacciones = finalRefacciones.filter((r: any) => {
                            const rName = r.pieza?.trim().toLowerCase() || '';
                            const rNameClean = rName.replace(' (material)', '').trim();

                            if (qConceptNames.includes(rNameClean)) return false;
                            if (qMaterialNames.includes(rNameClean)) return false;

                            return true;
                        });
                    }

                    // esCotizacion es true SOLO si la actividad contiene datos de cotización sugeridos por el técnico
                    const esCot = qData !== null;

                    return {
                        id: act.id,
                        titulo: act.tipo,
                        descripcion: displayDesc,
                        cleanDescripcion: cleanDesc,
                        rawDescripcion: finalDesc,
                        estado: "Nueva",
                        tecnicoNombre: authorName,
                        esCotizacion: esCot,
                        cotizacionMonto: parsedMonto,
                        cotizacionDetalles: displayDesc,
                        cotizacionArchivo: "",
                        cotizacionEstado: "Sugerencia de Técnico",
                        serviceData: sData,
                        hasQuote: finalDesc.includes(quoteMarker),
                        quoteData: qData,
                        refacciones: finalRefacciones,
                        photos: photosList
                    };
                });
                setSubTareas(mappedSubTareas as any);

                // Cargar cotizaciones reales (array)
                try {
                    let cotizs = await getCotizacionesByTrabajoId(Number(id));

                    // Auto-heal / Auto-creación de cotización en backend para SOS si el técnico ya registró subTareas con cotización
                    const isSOSJob = Boolean(trabajo?.tipo === "SOS" || trabajo?.prioridad === "Emergencia" || (trabajo?.titulo || '').includes("SOS") || (trabajo as any)?.isEmergency);
                    if (cotizs.length === 0 && isSOSJob && mappedSubTareas.some((st: any) => st.hasQuote || st.quoteData || (st.cotizacionMonto && st.cotizacionMonto !== 'Por Evaluar'))) {
                        let totalCalculado = 0;
                        const quoteDescriptions: string[] = [];

                        mappedSubTareas.forEach((st: any, idx: number) => {
                            let stTotal = 0;
                            if (st.quoteData) {
                                if (st.quoteData.conceptos && Array.isArray(st.quoteData.conceptos)) {
                                    for (const c of st.quoteData.conceptos) {
                                        stTotal += (Number(c.cantidad) || 1) * (Number(c.precio) || 0);
                                    }
                                }
                                if (st.quoteData.materiales && Array.isArray(st.quoteData.materiales)) {
                                    for (const m of st.quoteData.materiales) {
                                        stTotal += (Number(m.cantidad) || 1) * (Number(m.precio) || 0);
                                    }
                                }
                                if (stTotal === 0 && st.quoteData.monto) {
                                    stTotal = parseFloat(String(st.quoteData.monto).replace(/[^0-9.]/g, '')) || 0;
                                }
                            } else if (st.cotizacionMonto && !isNaN(Number(String(st.cotizacionMonto).replace(/[^0-9.]/g, '')))) {
                                stTotal = parseFloat(String(st.cotizacionMonto).replace(/[^0-9.]/g, '')) || 0;
                            }
                            totalCalculado += stTotal;
                            const pointName = st.titulo || `Punto #${idx + 1}`;
                            quoteDescriptions.push(`${pointName}: $${stTotal.toLocaleString('es-MX', { minimumFractionDigits: 2 })}`);
                        });

                        if (totalCalculado > 0) {
                            try {
                                const formData = new FormData();
                                formData.append('trabajo_id', String(id));
                                formData.append('monto', String(totalCalculado));
                                formData.append('total', String(totalCalculado));
                                const desc = `Cotización de Emergencia SOS - ${trabajo?.titulo || 'Servicio'}\n` + quoteDescriptions.join('\n');
                                formData.append('descripcion', desc);
                                formData.append('dias_estimados', '1');
                                formData.append('estado', 'Pendiente');

                                const savedCotiz = await saveCotizacion(formData as any);
                                cotizs = [savedCotiz];
                            } catch (autoCotErr) {
                                console.warn("Auto-creación de cotización SOS:", autoCotErr);
                            }
                        }
                    }

                    setCotizaciones(cotizs);
                    // Compat: si hay cotizaciones, ponemos la primera en trabajo.cotizacion para compatible con otros usos
                    if (cotizs.length > 0) {
                        const first = cotizs[0];
                        setTrabajo((prev: any) => prev ? {
                            ...prev,
                            cotizacion: {
                                id: first.id,
                                costo: first.monto,
                                notas: first.descripcion || "",
                                archivo: first.archivo || "",
                                fecha: first.updated_at ? new Date(first.updated_at).toLocaleDateString('es-MX') : ""
                            }
                        } : prev);

                        // Recuperar historial de cotizaciones desde el campo descripcion del backend
                        const HISTORY_MARKER = '|||QUOTE_HISTORY|||';
                        let backendHistory: any[] = [];
                        for (const cot of cotizs) {
                            if (cot.descripcion && cot.descripcion.includes(HISTORY_MARKER)) {
                                try {
                                    const historyJson = cot.descripcion.split(HISTORY_MARKER)[1].trim();
                                    const parsed = JSON.parse(historyJson);
                                    if (Array.isArray(parsed)) {
                                        backendHistory = parsed;
                                        break;
                                    }
                                } catch (e) { /* ignore */ }
                            }
                        }
                        if (backendHistory.length > 0) {
                            setQuoteHistory(backendHistory);
                            // Sincronizar también localStorage como caché local
                            localStorage.setItem(`quote_history_${id}`, JSON.stringify(backendHistory));
                        }
                    }
                } catch (e) { console.log('Sin cotizaciones previas'); }

            } catch (error) {
                console.error("Error al cargar historial desde Laravel:", error);
            }
        };
        fetchActividades();
    }, [id]);


