    const handleSaveExecutionTime = async () => {
        if (!execFecha) {
            showAlert("Atención", "Por favor selecciona la fecha de ejecución.", "warning");
            return;
        }
        setIsSavingExecTime(true);
        try {
            if (trabajo?.id) {
                await updateTrabajo(trabajo.id, {
                    fecha_programada: execFecha,
                    horaAsignada: execHora || '09:00'
                });

                const newCount = execModCount + 1;
                localStorage.setItem(`exec_time_mod_count_${trabajo.id}`, newCount.toString());
                localStorage.setItem(`trabajo_updated_${trabajo.id}`, Date.now().toString());
                setExecModCount(newCount);

                try {
                    await createNotificacionByRole({
                        role: 'encargado',
                        titulo: '📅 Fecha de Ejecución Confirmada',
                        mensaje: `El técnico ${user?.name || ''} ha confirmado la fecha de ejecución para el ${execFecha} a las ${execHora || '09:00'} en ${trabajo?.sucursal || ''}.`,
                        enlace: `/encargado/trabajo-detalle/${trabajo.id}`
                    });
                    await createNotificacionByRole({
                        role: 'admin',
                        titulo: '📅 Fecha de Ejecución Confirmada',
                        mensaje: `El técnico ${user?.name || ''} ha confirmado la fecha de ejecución para el ${execFecha} a las ${execHora || '09:00'} en ${trabajo?.sucursal || ''}.`,
                        enlace: `/menu/trabajo-detalle/${trabajo.id}`
                    });
                    if (trabajo.admin_autonomo_id) {
                        try {
                            await createNotificacion({
                                user_id: trabajo.admin_autonomo_id,
                                titulo: '📅 Fecha de Ejecución Confirmada',
                                mensaje: `El técnico ${user?.name || ''} ha confirmado la fecha de ejecución para el ${execFecha} a las ${execHora || '09:00'} en ${trabajo?.sucursal || ''}.`,
                                enlace: `/autonomo/trabajo-detalle/${trabajo.id}`
                            });
                        } catch (_) { }
                    }
                } catch (e) { }

                setTrabajo(prev => prev ? {
                    ...prev,
                    fecha_programada: execFecha,
                    horaAsignada: execHora || '09:00',
                    hora_programada: execHora || '09:00'
                } : prev);

                setIsEditingExecutionTime(false);
                showAlert(
                    "Horario Confirmado",
                    newCount >= 2
                        ? "Has utilizado tu única modificación permitida. La fecha y hora han quedado confirmadas de manera definitiva."
                        : "Has guardado la fecha y hora de ejecución del trabajo.",
                    "success"
                );
            }
        } catch (error) {
            showAlert("Error", "No se pudo guardar la fecha y hora de ejecución.", "error");
        } finally {
            setIsSavingExecTime(false);
        }
    };

    /** Técnico → Iniciar Ejecución del Trabajo */
    const handleIniciarEjecucionTrabajo = async () => {
        if (!trabajo?.id) return;
        try {
            if (trabajo.estado !== 'En Ejecución') {
                await updateTrabajo(trabajo.id, { estado: 'En Ejecución' });
                setTrabajo(prev => prev ? { ...prev, estado: 'En Ejecución' } : prev);
                localStorage.setItem(`trabajo_updated_${trabajo.id}`, Date.now().toString());

                try {
                    if (trabajo.admin_autonomo_id) {
                        await createNotificacion({
                            user_id: trabajo.admin_autonomo_id,
                            titulo: '🚀 Ejecución de Trabajo Iniciada',
                            mensaje: `El técnico ${user?.name || trabajo.tecnico || ''} ha iniciado la ejecución del trabajo en "${trabajo.sucursal || 'la sucursal'}".`,
                            enlace: `/autonomo/trabajo-detalle/${trabajo.id}`
                        });
                    }
                    await createNotificacionByRole({
                        role: 'admin',
                        titulo: '🚀 Ejecución de Trabajo Iniciada',
                        mensaje: `El técnico ${user?.name || trabajo.tecnico || ''} ha iniciado la ejecución del trabajo en "${trabajo.sucursal || 'la sucursal'}".`,
                        enlace: `/menu/trabajo-detalle/${trabajo.id}`
                    });
                    await createNotificacionByRole({
                        role: 'encargado',
                        titulo: '🚀 Ejecución de Trabajo Iniciada',
                        mensaje: `El técnico ${user?.name || trabajo.tecnico || ''} ha iniciado la ejecución del trabajo en "${trabajo.sucursal || 'la sucursal'}".`,
                        enlace: `/encargado/trabajo-detalle/${trabajo.id}`
                    });
                } catch (notifErr) {
                    console.error("Error sending start notifications:", notifErr);
                }

                showAlert(
                    "¡Trabajo en Ejecución!",
                    "Has iniciado formalmente la ejecución de este trabajo. El Administrador ha sido notificado.",
                    "success"
                );
            }

            if (subTareas && subTareas.length > 0) {
                const firstPending = subTareas.find(t => t.estado !== 'Completa' && !localStorage.getItem(`report_data_${t.id}`)) || subTareas[0];
                handleAbrirReporteTarea(firstPending.id);
            } else {
                handleAbrirReporteTarea();
            }
        } catch (err: any) {
            console.error("Error iniciando ejecución del trabajo:", err);
            showAlert("Error", "No se pudo actualizar el estado del trabajo a En Ejecución.", "error");
        }
    };


    const handleNewQuoteFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files.length > 0) {
            const file = e.target.files[0];
            setNewQuoteFileName(file.name);
            const reader = new FileReader();
            reader.onload = () => {
                // Archivo procesado
            };
            reader.readAsDataURL(file);
        }
    };

    const compressImage = (file: File, callback: (compressedBase64: string) => void) => {
        const reader = new FileReader();
        reader.onload = (e) => {
            const img = new Image();
            img.onload = () => {
                const canvas = document.createElement('canvas');
                const MAX_WIDTH = 800;
                const MAX_HEIGHT = 800;
                let width = img.width;
                let height = img.height;

                if (width > height) {
                    if (width > MAX_WIDTH) {
                        height *= MAX_WIDTH / width;
                        width = MAX_WIDTH;
                    }
                } else {
                    if (height > MAX_HEIGHT) {
                        width *= MAX_HEIGHT / height;
                        height = MAX_HEIGHT;
                    }
                }
                canvas.width = width;
                canvas.height = height;
                const ctx = canvas.getContext('2d');
                ctx?.drawImage(img, 0, 0, width, height);
                const dataUrl = canvas.toDataURL('image/jpeg', 0.6);
                callback(dataUrl);
            };
            if (e.target?.result) {
                img.src = e.target.result as string;
            }
        };
        reader.readAsDataURL(file);
    };

    const handleActivityPhotosChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files) {
            const files = Array.from(e.target.files);
            files.forEach((file) => {
                compressImage(file, (base64) => {
                    setActivityPhotos(prev => [...prev, base64]);
                });
            });
        }
    };


    const filteredTechnicians = tecnicosData.filter(t =>
        t.nombre.toLowerCase().includes(technicianSearch.toLowerCase())
    );

    const handleConfirmAssignment = async () => {
        if (trabajo && selectedTechnicians.length > 0) {
            const assignedNames = selectedTechnicians
                .map(id => tecnicosData.find(t => t.id === id)?.nombre)
                .filter(Boolean)
                .join(", ");

            if (assignedNames) {
                try {
                    // Update in Backend (parallel unified update for grouped jobs or single job)
                    const jobsToAssign = (groupedJobs && groupedJobs.length > 0) ? groupedJobs : [trabajo];

                    await Promise.all(jobsToAssign.map(async (currentJob) => {
                        const isQuoteState = currentJob.estado === "Cotización Enviada" || currentJob.estado === "Reasignación Solicitada";
                        const isCotizacionAprobadaReassign = currentJob.estado === "Cotización Aceptada" || currentJob.estado === "Cotización Aprobada";

                        let currentNewEstado: string;
                        if (isQuoteState && currentJob.tipo === "Visita") {
                            currentNewEstado = "Cotización Enviada";
                        } else if (isCotizacionAprobadaReassign) {
                            currentNewEstado = "Asignado";
                        } else {
                            const needsStateUpdate = currentJob.estado === "Pendiente" || currentJob.estado === "Solicitud" || currentJob.estado === "En Espera" || currentJob.estado === "Reasignación Solicitada" || currentJob.estado === "Rechazada";
                            currentNewEstado = needsStateUpdate ? "Asignado" : currentJob.estado;
                            localStorage.removeItem(`reassign_reason_${currentJob.id}`);
                        }

                        let currentNuevoTitulo = currentJob.titulo || "";
                        if (selectedType === "Trabajo" && currentNuevoTitulo.includes("(Visita)")) {
                            currentNuevoTitulo = currentNuevoTitulo.replace("(Visita)", "(Reparación)");
                        } else if (selectedType === "Visita" && currentNuevoTitulo.includes("(Reparación)")) {
                            currentNuevoTitulo = currentNuevoTitulo.replace("(Reparación)", "(Visita)");
                        }

                        const finalTipo = isSOS ? "SOS" : selectedType;

                        await updateTrabajo(currentJob.id, {
                            trabajador_id: selectedTechnicians[0],
                            estado: currentNewEstado,
                            visitado: selectedType === "Trabajo",
                            tipo: finalTipo,
                            titulo: currentNuevoTitulo,
                            fecha_programada: asignarFecha || undefined,
                            horaAsignada: asignarHora || undefined,
                            motivo_reasignacion: null,
                            motivo_rechazo: null
                        });
                    }));

                    // Calculate state for current single view job
                    const isQuoteState = trabajo.estado === "Cotización Enviada" || trabajo.estado === "Reasignación Solicitada";
                    const isCotizacionAprobadaReassign = trabajo.estado === "Cotización Aceptada" || trabajo.estado === "Cotización Aprobada";

                    let newEstado: string;
                    if (isQuoteState && trabajo.tipo === "Visita") {
                        newEstado = "Cotización Enviada";
                    } else if (isCotizacionAprobadaReassign) {
                        newEstado = "Asignado";
                    } else {
                        const needsStateUpdate = trabajo.estado === "Pendiente" || trabajo.estado === "Solicitud" || trabajo.estado === "En Espera" || trabajo.estado === "Reasignación Solicitada" || trabajo.estado === "Rechazada";
                        newEstado = needsStateUpdate ? "Asignado" : trabajo.estado;
                    }

                    localStorage.removeItem(`reassign_reason_${trabajo.id}`);

                    let nuevoTitulo = trabajo.titulo || "";
                    if (selectedType === "Trabajo" && nuevoTitulo.includes("(Visita)")) {
                        nuevoTitulo = nuevoTitulo.replace("(Visita)", "(Reparación)");
                    } else if (selectedType === "Visita" && nuevoTitulo.includes("(Reparación)")) {
                        nuevoTitulo = nuevoTitulo.replace("(Reparación)", "(Visita)");
                    }

                    const updatedJob = {
                        ...trabajo,
                        tecnico: assignedNames,
                        estado: newEstado,
                        tipo: isSOS ? "SOS" : selectedType,
                        originalTipo: isSOS ? "SOS" : selectedType,
                        titulo: nuevoTitulo,
                        motivo_reasignacion: null,
                        motivo_rechazo: null,
                        visitado: isSOS ? false : (selectedType === "Trabajo"),
                        fechaAsignada: asignarFecha,
                        horaAsignada: asignarHora
                    };
                    setTrabajo(updatedJob);

                    if (groupedJobs && groupedJobs.length > 0) {
                        setGroupedJobs(prev => prev.map(gj => {
                            const isQuote = gj.estado === "Cotización Enviada" || gj.estado === "Reasignación Solicitada";
                            const isCotApp = gj.estado === "Cotización Aceptada" || gj.estado === "Cotización Aprobada";
                            let gEstado = gj.estado;
                            if (isQuote && gj.tipo === "Visita") gEstado = "Cotización Enviada";
                            else if (isCotApp) gEstado = "Asignado";
                            else if (gj.estado === "Pendiente" || gj.estado === "Solicitud" || gj.estado === "En Espera") gEstado = "Asignado";

                            let gTitulo = gj.titulo || "";
                            if (selectedType === "Trabajo" && gTitulo.includes("(Visita)")) gTitulo = gTitulo.replace("(Visita)", "(Reparación)");
                            else if (selectedType === "Visita" && gTitulo.includes("(Reparación)")) gTitulo = gTitulo.replace("(Reparación)", "(Visita)");

                            return {
                                ...gj,
                                tecnico: assignedNames,
                                estado: gEstado,
                                tipo: selectedType,
                                titulo: gTitulo,
                                trabajador_id: selectedTechnicians[0],
                                trabajador: { id: selectedTechnicians[0], user_id: selectedTechnicians[0], nombre: assignedNames }
                            };
                        }));
                    }

                    // Notificaciones al técnico (backend + localStorage fallback)
                    const esSOS = trabajo.tipo === "SOS" || trabajo.titulo?.includes("SOS");
                    const isVisita = selectedType === "Visita";
                    const notifTitulo = esSOS
                        ? '🚨 Trabajo de Emergencia SOS'
                        : (isVisita ? '📋 Nueva Visita Asignada' : '🛠️ Nuevo Trabajo Asignado');
                    const notifMensaje = esSOS
                        ? `⚠️ EMERGENCIA: Se te ha asignado un trabajo urgente en ${trabajo.sucursal}. Atender de inmediato: "${trabajo.titulo}".`
                        : (isVisita
                            ? `Se te ha asignado una nueva visita de evaluación para: ${trabajo.titulo} en ${trabajo.sucursal}.`
                            : `Te han asignado un nuevo trabajo: ${trabajo.titulo} en ${trabajo.sucursal}.`);

                    for (const id of selectedTechnicians) {
                        const tech = tecnicosData.find(t => t.id === id);
                        if (!tech) continue;

                        // 1. Notificación backend (la que aparece en el panel del técnico)
                        if (tech.user_id) {
                            try {
                                await createNotificacion({
                                    user_id: tech.user_id,
                                    titulo: notifTitulo,
                                    mensaje: notifMensaje,
                                    enlace: `/tecnico/trabajo-detalle/${trabajo.id}`
                                });
                            } catch (notiErr) {
                                console.error("Error enviando notificación al técnico:", notiErr);
                            }
                        }

                        // 2. localStorage como fallback visual inmediato
                        const techKey = `tecnico_notifications_${tech.nombre}`;
                        const techNotifs = JSON.parse(localStorage.getItem(techKey) || '[]');
                        techNotifs.unshift({
                            id: Date.now() + Math.random(),
                            titulo: notifTitulo,
                            mensaje: notifMensaje,
                            fecha: new Date().toLocaleDateString('es-MX', { hour: '2-digit', minute: '2-digit' }),
                            leida: false,
                            jobId: trabajo.id
                        });
                        localStorage.setItem(techKey, JSON.stringify(techNotifs));
                    }
                    window.dispatchEvent(new Event('storage'));
                    showAlert(
                        'Técnico Asignado',
                        'El técnico ha sido asignado exitosamente al trabajo.',
                        'success'
                    );
                } catch (error) {
                    console.error("Error asignando técnico:", error);
                    showAlert(
                        'Error de Servidor',
                        'Hubo un problema al conectar con la base de datos.',
                        'error'
                    );
                }
            }
        }
        setIsModalOpen(false);
    };

    const handleAceptarAsignacion = async () => {
        if (!trabajo) return;
        try {
            await updateEstadoTrabajo(trabajo.id, { estado: "En Espera" });
            setTrabajo((prev: any) => prev ? { ...prev, estado: "En Espera" } : prev);

            try {
                await createNotificacionByRole({
                    role: 'admin',
                    titulo: isSOS ? '🚨 Emergencia SOS Aceptada' : '✅ Asignación Aceptada',
                    mensaje: `El técnico ${user?.name || 'asignado'} ha aceptado el trabajo en "${trabajo.sucursal || 'Sucursal'}".`,
                    enlace: `/autonomo/trabajo-detalle/${trabajo.id}`
                });
            } catch (e) { }

            if (trabajo.negocio_id) {
                try {
                    const negocioRes = await getNegocio(trabajo.negocio_id);
                    const negocioData = negocioRes?.data || negocioRes;
                    if (negocioData?.admin_autonomo_id) {
                        await createNotificacionEcosistema({
                            admin_autonomo_id: negocioData.admin_autonomo_id,
                            titulo: isSOS ? '🚨 Emergencia SOS Aceptada' : '✅ Asignación Aceptada',
                            mensaje: `El técnico ${user?.name || 'asignado'} ha aceptado el trabajo para ${negocioData.nombre || 'sucursal'}.`,
                            tipo: 'Info'
                        });
                    }
                } catch (e) { }
            }

            if (isSOS) {
                showAlert("Emergencia Aceptada", "Has aceptado la asignación de emergencia. Ahora puedes iniciar la visita cuando llegues a la sucursal.", "success");
            } else {
                showAlert("Trabajo Aceptado", "Has aceptado la asignación. Ahora puedes iniciar la visita cuando llegues a la sucursal.", "success");
            }
            setShowZoomModal(false);
        } catch (error) {
            console.error("Error aceptando asignación:", error);
            showAlert("Error", "No se pudo aceptar la asignación.", "error");
        }
    };

    const handleConfirmHoraLlegada = async () => {
        if (!horaLlegada) {
            showAlert("Atención", "Debes indicar una hora estimada de llegada.", "warning");
            return;
        }

        try {
            await updateEstadoTrabajo(trabajo.id, { estado: "En Espera", hora_llegada: horaLlegada });
            setTrabajo((prev: any) => prev ? { ...prev, estado: "En Espera", hora_llegada: horaLlegada } : prev);

            // Notificar al encargado y admin autonomo
            if (trabajo.negocio_id) {
                const negocioRes = await getNegocio(trabajo.negocio_id);
                const negocioData = negocioRes.data || negocioRes;
                if (negocioData) {
                    try {
                        await createNotificacionNegocio({
                            negocio_id: trabajo.negocio_id,
                            titulo: 'Técnico en camino',
                            mensaje: `El técnico ha aceptado la solicitud y estima llegar a las ${horaLlegada}.`,
                        });
                    } catch (e) { console.error("Error notificando encargado:", e); }

                    if (config.notificarEcosistema && negocioData.admin_autonomo_id) {
                        try {
                            await createNotificacionEcosistema({
                                admin_autonomo_id: negocioData.admin_autonomo_id,
                                titulo: 'Técnico en camino',
                                mensaje: `El técnico ha aceptado la solicitud para ${negocioData.nombre} y estima llegar a las ${horaLlegada}.`,
                                tipo: 'Info'
                            });
                        } catch (e) { console.error("Error notificando autonomo:", e); }
                    }
                }
            }

            setShowHoraLlegadaModal(false);
            showAlert("Trabajo Aceptado", `Has aceptado la asignación. Llegada estimada a las ${horaLlegada}.`, "success");
        } catch (error) {
            console.error("Error aceptando asignación:", error);
            showAlert("Error", "No se pudo aceptar la asignación.", "error");
        }
    };
    const handleRechazarAsignacion = () => {
        setRejectionMode("solicitud");
        setRejectionReason("");
        setShowRejectionModal(true);
    };


    const handleEmpezarTrabajoTipo = async (tipo: 'Visita' | 'Trabajo') => {
        try {
            const isVisita = tipo === 'Visita';
            const nuevoTitulo = trabajo.titulo ? trabajo.titulo.replace("(Visita)", "").replace("(Reparación)", "").trim() + (isVisita ? " (Visita)" : " (Reparación)") : (isVisita ? "Nueva Visita" : "Nueva Reparación");

            await updateEstadoTrabajo(trabajo.id, { estado: "En Proceso", visitado: !isVisita });
            await updateTrabajo(trabajo.id, { tipo, titulo: nuevoTitulo });

            setTrabajo((prev: any) => prev ? { ...prev, estado: "En Proceso", tipo, originalTipo: prev.originalTipo || tipo, titulo: nuevoTitulo, visitado: !isVisita } : prev);
            setActiveTab(isVisita ? 'Registro' : 'Trabajo');
            showAlert("Actividad Iniciada", `Has iniciado como ${tipo}. Ahora puedes agregar registros.`, "success");
        } catch (error) {
            console.error("Error iniciando trabajo:", error);
            showAlert("Error", "No se pudo iniciar la actividad.", "error");
        }
    };
    const handleGeneratePreview = () => {
        const activeItems = taskItems.filter(t => t.descripcion.trim() || t.foto);
        const combinedDescText = activeItems.length > 0
            ? activeItems.map((item, idx) => {
                const tipoLabel = item.tipoActividad === 'Otro' ? (item.customTipoActividad || 'Otro') : (item.tipoActividad || 'Mantenimiento');
                const text = item.descripcion.trim();
                return activeItems.length > 1 ? `${idx + 1}. [${tipoLabel}] ${text}` : `[${tipoLabel}] ${text}`;
            }).filter(Boolean).join('\n\n')
            : newTaskDescription;

        const selectedCategories = Array.from(new Set(
            activeItems.map(it => it.tipoActividad === 'Otro' ? (it.customTipoActividad || 'Otro') : it.tipoActividad).filter(Boolean)
        ));
        const combinedCategories = selectedCategories.length > 0
            ? selectedCategories.join(', ')
            : (activeServiceType === 'Otro' ? (customServiceType || 'Otro') : activeServiceType);

        const perPointRefaccionesList: any[] = [];
        activeItems.forEach((it, idx) => {
            if (it.isQuoteIncluded !== false) {
                (it.quoteConceptos || []).forEach(c => {
                    if (c.descripcion?.trim() || c.precio) {
                        perPointRefaccionesList.push({
                            pieza: activeItems.length > 1 ? `[Punto ${idx + 1}] ${c.descripcion}` : c.descripcion,
                            cantidad: Number(c.cantidad) || 1,
                            costo_estimado: c.precio ? String(c.precio) : ''
                        });
                    }
                });
                (it.quoteMateriales || []).forEach(m => {
                    if (m.nombre?.trim() || m.precio) {
                        perPointRefaccionesList.push({
                            pieza: activeItems.length > 1 ? `[Punto ${idx + 1}] ${m.nombre}` : m.nombre,
                            cantidad: Number(m.cantidad) || 1,
                            costo_estimado: m.precio ? String(m.precio) : ''
                        });
                    }
                });
            }
        });

        const refaccionesList = refacciones.map(r => ({
            pieza: r.pieza,
            cantidad: Number(r.cantidad) || 1,
            costo_estimado: r.costo_estimado ? String(r.costo_estimado) : ''
        })).concat(perPointRefaccionesList);

        const combinedMateriales = quoteComentarios || '';

        const preparedData = {
            id: trabajo?.id || 'SD',
            folio: `COT-${trabajo?.id?.toString().padStart(5, '0')}`,
            sucursal: trabajo?.sucursal || '---',
            encargado: trabajo?.encargado || '---',
            tecnico: user?.name || trabajo?.tecnico || 'Técnico',
            isVisita: !trabajo?.visitado,
            reporteTienda: combinedCategories,
            descripcion: combinedDescText,
            materiales: combinedMateriales,
            refaccionesList: refaccionesList,
            observaciones: '',
            puntosEvidencia: activeItems.map((item, index) => ({
                punto: index + 1,
                tipo: item.tipoActividad === 'Otro' ? item.customTipoActividad : item.tipoActividad,
                descripcion: item.descripcion,
                foto: item.foto
            })).filter(p => p.foto || p.descripcion),
            observacionesList: activeItems.map((item, index) => ({
                id: String(index + 1),
                texto: item.descripcion,
                imagenes: item.foto ? [item.foto] : []
            })),
            imagenes: {
                antes: activeItems[0]?.foto || activityPhotos[0] || null,
                durante: activeItems[1]?.foto || activityPhotos[1] || null,
                despues: activeItems[2]?.foto || activityPhotos[2] || null
            },
            imagenObservacion: activeItems[3]?.foto || activityPhotos[3] || null,
            imagenesObservacion: activeItems[3]?.foto ? [activeItems[3].foto] : [],
            firmaEmpresa: null,
            involucraEquipo: !!serviceMarca || !!serviceModelo,
            equipoInfo: (serviceMarca || serviceModelo) ? {
                tipo: activeServiceType,
                marca: serviceMarca || 'N/A',
                modelo: serviceModelo || 'N/A',
                piezas: servicePieza || 'N/A',
                garantia: serviceGarantia || 'N/A'
            } : null,
            fecha: new Date().toLocaleDateString('es-MX')
        };

        setActivityPDFData(preparedData);
        setShowActivityPDFPreview(true);
    };

    const buildTechQuoteReportData = (targetTarea: any, refSource: any[] = []) => {
        const tId = targetTarea?.id;
        const pIdx = targetTarea?.pointIndex;
        const baseId = targetTarea?.baseId;
        const workId = trabajo?.id;

        const candidateKeys = [
            `report_data_${tId}`,
            `report_data_temporal_${tId}`,
            workId ? `report_data_${workId}_${tId}` : '',
            workId ? `report_data_temporal_${workId}_${tId}` : '',
            baseId && pIdx !== undefined ? `report_data_${baseId}_${pIdx}` : '',
            baseId && pIdx !== undefined ? `report_data_temporal_${baseId}_${pIdx}` : '',
            workId && pIdx !== undefined ? `report_data_${workId}_${pIdx}` : '',
            workId && pIdx !== undefined ? `report_data_temporal_${workId}_${pIdx}` : '',
            workId ? `report_data_${workId}` : '',
            workId ? `report_data_temporal_${workId}` : ''
        ].filter(Boolean);

        let foundReport: any = null;
        for (const k of candidateKeys) {
            const raw = localStorage.getItem(k);
            if (raw) {
                try {
                    const parsed = JSON.parse(raw);
                    if (parsed && (parsed.imagenes || parsed.observacionesList || parsed.puntosEvidencia || parsed.descripcion || parsed.reporteTienda)) {
                        foundReport = parsed;
                        break;
                    }
                } catch (_) { }
            }
        }
        if (!foundReport) {
            foundReport = reporteFinal || null;
        }

        // Build quote items list (conceptos + materiales + refacciones)
        const quoteItems: any[] = [];
        if (targetTarea?.quoteData?.conceptos && targetTarea.quoteData.conceptos.length > 0) {
            targetTarea.quoteData.conceptos.forEach((c: any) => {
                quoteItems.push({
                    pieza: c.descripcion,
                    cantidad: Number(c.cantidad || 1),
                    costo_estimado: String(c.precio || 0)
                });
            });
        }
        if (targetTarea?.quoteData?.materiales && targetTarea.quoteData.materiales.length > 0) {
            targetTarea.quoteData.materiales.forEach((m: any) => {
                quoteItems.push({
                    pieza: m.nombre,
                    cantidad: Number(m.cantidad || 1),
                    costo_estimado: String(m.precio || 0)
                });
            });
        }
        if (quoteItems.length === 0) {
            const mergedRefs = getMergedRefacciones(targetTarea, refSource.length > 0 ? refSource : (foundReport?.refaccionesList || []));
            mergedRefs.forEach((r: any) => {
                quoteItems.push({
                    pieza: r.pieza,
                    cantidad: Number(r.cantidad || 1),
                    costo_estimado: String(r.costo_estimado || 0)
                });
            });
        }

        // Evidence / Photos:
        const allTaskPhotos: string[] = [];
        if (targetTarea?.photos && Array.isArray(targetTarea.photos)) {
            targetTarea.photos.forEach((p: string) => { if (p && !allTaskPhotos.includes(p)) allTaskPhotos.push(p); });
        }
        subTareas.forEach((st: any) => {
            if (st.photos && Array.isArray(st.photos)) {
                st.photos.forEach((p: string) => { if (p && !allTaskPhotos.includes(p)) allTaskPhotos.push(p); });
            }
            if (st.imagenObservacion && !allTaskPhotos.includes(st.imagenObservacion)) {
                allTaskPhotos.push(st.imagenObservacion);
            }
            if (st.imagenesObservacion && Array.isArray(st.imagenesObservacion)) {
                st.imagenesObservacion.forEach((p: string) => { if (p && !allTaskPhotos.includes(p)) allTaskPhotos.push(p); });
            }
        });

        const imgs = foundReport?.imagenes || {
            antes: allTaskPhotos[0] || null,
            durante: allTaskPhotos[1] || null,
            despues: allTaskPhotos[2] || null
        };

        const imgObs = foundReport?.imagenObservacion || (allTaskPhotos.length > 3 ? allTaskPhotos[3] : null);
        const imgsObs = (foundReport?.imagenesObservacion && foundReport.imagenesObservacion.length > 0)
            ? foundReport.imagenesObservacion
            : (allTaskPhotos.length > 0 ? allTaskPhotos : []);

        const puntosEvi = foundReport?.puntosEvidencia || (
            subTareas.length > 0
                ? subTareas.map((st, idx) => ({
                    punto: idx + 1,
                    tipo: st.serviceData?.tipoServicio || st.tipoActividad || st.titulo || `Punto ${idx + 1}`,
                    descripcion: st.descripcion || '',
                    foto: st.photos?.[0] || st.imagenObservacion || allTaskPhotos[idx] || null
                })).filter(p => p.foto || p.descripcion)
                : allTaskPhotos.map((p, idx) => ({
                    punto: idx + 1,
                    tipo: targetTarea?.serviceData?.tipoServicio || targetTarea?.titulo || `Punto ${idx + 1}`,
                    descripcion: targetTarea?.descripcion || '',
                    foto: p
                }))
        );

        // Equipment:
        const eqInfo = foundReport?.equipoInfo || (
            (targetTarea?.serviceData?.marca || targetTarea?.serviceData?.modelo) ? {
                tipo: targetTarea.serviceData.tipoServicio || targetTarea.titulo || 'Mantenimiento',
                marca: targetTarea.serviceData.marca || 'N/A',
                modelo: targetTarea.serviceData.modelo || 'N/A',
                piezas: targetTarea.serviceData.pieza || 'N/A',
                garantia: targetTarea.serviceData.garantia || 'N/A'
            } : (maintenanceEquipmentList && maintenanceEquipmentList.length > 0 ? {
                tipo: maintenanceEquipmentList[0].nombre,
                marca: maintenanceEquipmentList[0].marca,
                modelo: maintenanceEquipmentList[0].modelo,
                piezas: 'N/A',
                garantia: 'N/A'
            } : null)
        );

        return {
            id: foundReport?.dbId || foundReport?.id || trabajo?.id || 'SD',
            folio: `COT-${(trabajo?.id || '').toString().padStart(5, '0')}`,
            fecha: foundReport?.fecha || new Date().toLocaleDateString('es-MX', { year: 'numeric', month: 'long', day: 'numeric' }),
            sucursal: trabajo?.sucursal || 'N/A',
            encargado: trabajo?.encargado || 'N/A',
            tecnicoNombre: foundReport?.tecnicoNombre || targetTarea?.tecnicoNombre || trabajo?.tecnico || 'N/A',
            tecnicoAvatar: foundReport?.tecnicoAvatar || getAvatarForTech(targetTarea?.tecnicoNombre || trabajo?.tecnico || ''),
            reporteTienda: foundReport?.reporteTienda || targetTarea?.titulo || trabajo?.servicio || 'Servicio',
            descripcion: foundReport?.descripcion || targetTarea?.descripcion || trabajo?.descripcion || 'Sin descripción',
            materiales: foundReport?.materiales || quoteItems.map((r: any) => `${r.cantidad || 1}x ${r.pieza}`).join(', ') || 'N/A',
            observaciones: targetTarea?.quoteData?.comentarios || foundReport?.observaciones || 'Sin observaciones',
            observacionesList: foundReport?.observacionesList,
            puntosEvidencia: puntosEvi,
            imagenes: imgs,
            imagenObservacion: imgObs,
            imagenesObservacion: imgsObs,
            refaccionesList: quoteItems,
            isVisita: true,
            involucraEquipo: Boolean(eqInfo),
            equipoInfo: eqInfo,
            firmaEmpresa: foundReport?.firmaEmpresa || null,
        };
    };

    const executeSendQuote = async () => {
        if (!quoteToSend || !trabajo) return;
        setIsSendingQuote(true);
        try {
            const previewData = buildTechQuoteReportData(
                quoteToSend,
                Array.isArray(refaccionesData?.data) ? refaccionesData.data : (refaccionesData || [])
            );

            const pdfFile = await generateMaintenanceReportPDF(previewData as any);

            const totalAmount = (previewData.refaccionesList || []).reduce((acc: number, ref: any) => {
                const qty = Number(ref.cantidad || 1);
                const unitPrice = parseFloat(ref.costo_estimado) || 0;
                return acc + (qty * unitPrice);
            }, 0);

            const formData = new FormData();
            formData.append('trabajo_id', trabajo?.id.toString() || '');
            formData.append('monto', totalAmount.toString());
            formData.append('descripcion', 'Cotización generada a partir de sugerencia del técnico.');
            if (pdfFile) {
                formData.append('archivo', pdfFile);
            }

            const savedCotiz = await saveCotizacion(formData as any);
            setCotizaciones(prev => [...prev, savedCotiz]);

            if (config.notificarEcosistema && trabajo?.admin_autonomo_id) {
                await createNotificacionEcosistema({
                    admin_autonomo_id: trabajo.admin_autonomo_id,
                    titulo: '📄 Nueva Cotización',
                    mensaje: `Se ha enviado una cotización sugerida para la sucursal ${trabajo.sucursal}.`,
                });
            }

            await updateEstadoTrabajo(trabajo!.id, { estado: 'Cotización Enviada' });
            setTrabajo(prev => prev ? { ...prev, estado: 'Cotización Enviada' } : prev);

            showAlert('Cotización Enviada', 'Se ha enviado la cotización al Admin Autónomo.', 'success');
            setShowSendQuoteConfirmModal(false);
            setQuoteToSend(null);
        } catch (error) {
            console.error("Error al enviar al admin autonomo:", error);
            showAlert('Error', 'Hubo un problema al enviar la cotización.', 'error');
        } finally {
            setIsSendingQuote(false);
        }
    };

    const handleAddTask = async (generatePDF = false) => {
        try {
            const activeItems = taskItems.filter(t => t.descripcion.trim() || t.foto);
            if (activeItems.length === 0 && !newTaskDescription.trim()) {
                showAlert("Descripción Requerida", "Por favor ingresa una descripción o detalle del trabajo realizado.", "warning");
                return;
            }

            // Validar que exista al menos un concepto de cotización con precio mayor a $0
            const hasValidQuote = activeItems.some(it =>
                it.isQuoteIncluded !== false &&
                (it.quoteConceptos || []).some(c => c.descripcion?.trim() && parseFloat(c.precio) > 0)
            );
            if (!hasValidQuote) {
                showAlert(
                    "Cotización Requerida",
                    "Debes ingresar la descripción y precio de cotización (mayor a $0) en los puntos de revisión antes de guardar.",
                    "warning"
                );
                return;
            }

            const combinedDesc = activeItems.length > 0
                ? activeItems.map((item, idx) => {
                    const tipoLabel = item.tipoActividad === 'Otro' ? (item.customTipoActividad || 'Otro') : (item.tipoActividad || 'Mantenimiento');
                    const text = item.descripcion.trim();
                    return activeItems.length > 1 ? `${idx + 1}. [${tipoLabel}] ${text}` : `[${tipoLabel}] ${text}`;
                }).filter(Boolean).join('\n\n')
                : newTaskDescription;
            const combinedPhotos = activeItems.map(t => t.foto).filter(Boolean);

            let desc = combinedDesc;

            const primaryItem = activeItems[0] || taskItems[0];
            const primaryTipo = (primaryItem?.tipoActividad === 'Otro' ? primaryItem?.customTipoActividad : primaryItem?.tipoActividad) || activeServiceType || 'Mantenimiento';

            // Serializar datos técnicos (Marca, Modelo, etc.)
            const serviceData = {
                tipoServicio: primaryTipo,
                marca: primaryItem?.marca || serviceMarca,
                modelo: primaryItem?.modelo || serviceModelo,
                pieza: primaryItem?.pieza || (primaryTipo === 'Instalacion' ? servicePieza : ''),
                garantia: primaryItem?.garantia || (primaryTipo === 'Instalacion' ? serviceGarantia : ''),
                llegadaConfirmada: confirmacionLlegada,
                horaLlegada: horaLlegada,
                items: activeItems.map(it => ({
                    tipo: it.tipoActividad || 'Mantenimiento',
                    customTipo: it.customTipoActividad || '',
                    descripcion: it.descripcion,
                    marca: it.marca || '',
                    modelo: it.modelo || '',
                    pieza: it.pieza || '',
                    garantia: it.garantia || '',
                    isQuoteIncluded: it.isQuoteIncluded,
                    quoteConceptos: it.quoteConceptos || [],
                    quoteMateriales: it.quoteMateriales || []
                }))
            };
            desc += ` \n|||SERVICE_DATA||| ${JSON.stringify(serviceData)}`;

            const allConceptos: any[] = [];
            const allMateriales: any[] = [];
            const itemsQuote = activeItems.map((it, idx) => {
                const ptConceptos = (it.quoteConceptos || []).filter(c => c.descripcion?.trim() || c.precio);
                const ptMateriales = (it.quoteMateriales || []).filter(m => m.nombre?.trim() || m.precio);
                
                if (it.isQuoteIncluded !== false) {
                    ptConceptos.forEach(c => {
                        if (c.descripcion?.trim() || c.precio) {
                            allConceptos.push({
                                ...c,
                                descripcion: activeItems.length > 1 ? `[Punto ${idx + 1}] ${c.descripcion}` : c.descripcion,
                                puntoIndex: idx + 1
                            });
                        }
                    });
                    ptMateriales.forEach(m => {
                        if (m.nombre?.trim() || m.precio) {
                            allMateriales.push({
                                ...m,
                                nombre: activeItems.length > 1 ? `[Punto ${idx + 1}] ${m.nombre}` : m.nombre,
                                puntoIndex: idx + 1
                            });
                        }
                    });
                }

                const subtotal = ptConceptos.reduce((acc, c) => acc + ((Number(c.cantidad) || 1) * (parseFloat(c.precio) || 0)), 0) +
                                 ptMateriales.reduce((acc, m) => acc + ((Number(m.cantidad) || 1) * (parseFloat(m.precio) || 0)), 0);

                return {
                    puntoIndex: idx + 1,
                    descripcion: it.descripcion,
                    tipo: it.tipoActividad || 'Mantenimiento',
                    marca: it.marca || '',
                    modelo: it.modelo || '',
                    isQuoteIncluded: it.isQuoteIncluded !== false,
                    conceptos: ptConceptos,
                    materiales: ptMateriales,
                    subtotal: subtotal
                };
            });

            if (allConceptos.length > 0 || allMateriales.length > 0) {
                const quotePayload = {
                    conceptos: allConceptos,
                    materiales: allMateriales,
                    comentarios: quoteComentarios,
                    itemsQuote: itemsQuote
                };
                desc += ` \n|||QUOTE_DATA||| ${JSON.stringify(quotePayload)}`;
            }

            const techNamePayload = user?.name || "Sin Asignar";
            desc += ` \n|||TECH_NAME||| ${techNamePayload}`;

            const finalPhotos = combinedPhotos.length > 0 ? combinedPhotos : activityPhotos;
            if (finalPhotos.length > 0) {
                desc += ` \n|||PHOTOS_DATA||| ${JSON.stringify(finalPhotos)}`;
            }

            const payloadRefacciones = refacciones
                .filter(r => r.pieza && r.pieza.trim() !== '')
                .map(r => ({
                    pieza: r.pieza.trim(),
                    cantidad: Number(r.cantidad),
                    costo_estimado: r.costo_estimado ? Number(r.costo_estimado) : undefined,
                    levantamiento_equipo_id: serviceEquipoId || undefined
                }));

            const body = {
                trabajo_id: Number(id),
                tipo: primaryTipo,
                descripcion: desc,
                refacciones: payloadRefacciones,
                estado: 'Completa'
            };

            if (editingTaskId) {
                await updateActividad(editingTaskId, body);
            } else {
                await createActividad(body);
            }

            // El estado solo cambia cuando el técnico presiona "Enviar al Administrador", no al guardar una actividad individual

            const acts = await getActividadesByTrabajo(Number(id));
            const mappedSubTareas = acts.map((act: any) => {
                let finalDesc = act.descripcion || "";
                let parsedMonto = "Por Evaluar";
                let sData = null;
                let qData = null;

                const quoteMarker = "|||QUOTE_DATA|||";
                const serviceMarker = "|||SERVICE_DATA|||";
                const techMarker = "|||TECH_NAME|||";
                const photosMarker = "|||PHOTOS_DATA|||";

                // Limpiamos la descripción mostrada de todos los marcadores técnicos
                const cleanDesc = finalDesc
                    .split(serviceMarker)[0]
                    .split(quoteMarker)[0]
                    .split(techMarker)[0]
                    .split(photosMarker)[0]
                    .trim();

                let displayDesc = cleanDesc;

                if (finalDesc.includes(serviceMarker)) {
                    const parts = finalDesc.split(serviceMarker);
                    try {
                        sData = JSON.parse(parts[1].split(quoteMarker)[0].split(techMarker)[0].split(photosMarker)[0].trim());
                    } catch (e) { }
                }

                if (finalDesc.includes(quoteMarker)) {
                    const parts = finalDesc.split(quoteMarker);
                    try {
                        const jsonContent = parts[1].split(serviceMarker)[0].split(techMarker)[0].split(photosMarker)[0].trim();
                        if (jsonContent.startsWith('{')) {
                            qData = JSON.parse(jsonContent);
                            if (qData.monto) parsedMonto = qData.monto;
                            if (qData.detalles) displayDesc += "\n\nNotas de cotización:\n" + qData.detalles;
                        } else {
                            // Plain text fallback
                            const firstHyphen = jsonContent.indexOf(" - ");
                            if (firstHyphen !== -1) {
                                const possibleMonto = jsonContent.substring(0, firstHyphen).trim();
                                if (!isNaN(Number(possibleMonto.replace('$', '')))) {
                                    parsedMonto = possibleMonto;
                                    const detailsText = jsonContent.substring(firstHyphen + 3).trim();
                                    qData = { monto: possibleMonto, detalles: detailsText };
                                } else {
                                    qData = { monto: "", detalles: jsonContent };
                                }
                            } else {
                                qData = { monto: "", detalles: jsonContent };
                            }
                            if (qData.detalles) displayDesc += "\n\nNotas de cotización:\n" + qData.detalles;
                        }
                    } catch (e) { }
                }

                let photosList: string[] = [];
                if (finalDesc.includes(photosMarker)) {
                    const parts = finalDesc.split(photosMarker);
                    try {
                        const jsonContent = parts[1].split(serviceMarker)[0].split(quoteMarker)[0].split(techMarker)[0].trim();
                        photosList = JSON.parse(jsonContent);
                    } catch (e) { }
                }

                const esCot = qData !== null;

                return {
                    id: act.id,
                    titulo: act.tipo,
                    descripcion: displayDesc,
                    cleanDescripcion: cleanDesc,
                    rawDescripcion: finalDesc,
                    estado: "Nueva",
                    tecnicoNombre: user?.name,
                    esCotizacion: esCot,
                    cotizacionMonto: parsedMonto,
                    cotizacionDetalles: displayDesc,
                    cotizacionArchivo: "",
                    cotizacionEstado: "Sugerencia de Técnico",
                    serviceData: sData,
                    hasQuote: finalDesc.includes(quoteMarker),
                    quoteData: qData,
                    refacciones: act.refacciones,
                    photos: photosList
                };
            });
            setSubTareas(mappedSubTareas as any);
            if (generatePDF) {
                // Conceptos de servicio (Mano de obra / servicios)
                const conceptosPDF = isQuoteIncluded ? quoteConceptos
                    .filter(c => c.descripcion && c.descripcion.trim())
                    .map(c => ({
                        pieza: c.descripcion,
                        cantidad: Number(c.cantidad) || 1,
                        costo_estimado: c.precio ? String(c.precio) : '0'
                    })) : [];

                // Materiales físicos
                const materialesPDF = isQuoteIncluded ? quoteMateriales
                    .filter(m => m.nombre && m.nombre.trim())
                    .map(m => ({
                        pieza: m.nombre,
                        cantidad: Number(m.cantidad) || 1,
                        costo_estimado: m.precio ? String(m.precio) : '0'
                    })) : [];

                // Refacciones adicionales del técnico
                const refaccionesBase = refacciones.map(r => ({
                    pieza: r.pieza,
                    cantidad: Number(r.cantidad) || 1,
                    costo_estimado: r.costo_estimado ? String(r.costo_estimado) : '0'
                }));

                // Combinar todos: conceptos + materiales + refacciones
                const refaccionesList = [...conceptosPDF, ...materialesPDF, ...refaccionesBase];


                const selectedCategories = Array.from(new Set(
                    activeItems.map(it => it.tipoActividad === 'Otro' ? (it.customTipoActividad || 'Otro') : it.tipoActividad).filter(Boolean)
                ));
                const combinedCategories = selectedCategories.length > 0
                    ? selectedCategories.join(', ')
                    : (activeServiceType === 'Otro' ? (customServiceType || 'Otro') : activeServiceType);

                const preparedData = {
                    id: trabajo?.id || 'SD',
                    folio: `COT-${trabajo?.id?.toString().padStart(5, '0')}`,
                    sucursal: trabajo?.sucursal || '---',
                    encargado: trabajo?.encargado || '---',
                    tecnico: user?.name || trabajo?.tecnico || 'Técnico',
                    isVisita: !trabajo?.visitado,
                    reporteTienda: combinedCategories,
                    descripcion: combinedDesc,
                    materiales: combinedMateriales,
                    refaccionesList: refaccionesList,
                    observaciones: '',
                    puntosEvidencia: activeItems.map((item, index) => ({
                        punto: index + 1,
                        tipo: item.tipoActividad === 'Otro' ? item.customTipoActividad : item.tipoActividad,
                        descripcion: item.descripcion,
                        foto: item.foto
                    })).filter(p => p.foto || p.descripcion),
                    imagenes: {
                        antes: activityPhotos[0] || null,
                        durante: activityPhotos[1] || null,
                        despues: activityPhotos[2] || null
                    },
                    imagenObservacion: activityPhotos[3] || null,
                    imagenesObservacion: activityPhotos[3] ? [activityPhotos[3]] : [],
                    firmaEmpresa: null,
                    involucraEquipo: !!serviceMarca || !!serviceModelo,
                    equipoInfo: (serviceMarca || serviceModelo) ? {
                        tipo: activeServiceType,
                        marca: serviceMarca || 'N/A',
                        modelo: serviceModelo || 'N/A',
                        piezas: servicePieza || 'N/A',
                        garantia: serviceGarantia || 'N/A'
                    } : null,
                    fecha: new Date().toLocaleDateString('es-MX')
                };

                setActivityPDFData(preparedData);
                setShowActivityPDFPreview(true);

                try {
                    await generateMaintenanceReportPDF(preparedData);
                } catch (err) {
                    console.error("Error generando PDF:", err);
                }
            }
            showAlert(
                'Actividad Registrada',
                'La actividad ha sido guardada y sincronizada correctamente.',
                'success'
            );
        } catch (error: any) {
            console.error("Error added task:", error);
            showAlert(
                'Error de API',
                error.response?.data?.message || error.message,
                'error'
            );
            return;
        }

        setIsAddModalOpen(false);
        setEditingTaskId(null);
        setNewTaskDescription("");
        setIsQuoteIncluded(false);
        setQuoteConceptos([]);
        setQuoteMateriales([]);
        setQuoteComentarios("");
        setActivityPhotos([]);
        // Reset service fields
        setServiceMarca("");
        setServiceModelo("");
        setServicePieza("");
        setServiceGarantia("");
        setRefacciones([]);

        // Siempre regresar a Registro para que el técnico pueda seguir agregando actividades
        setActiveTab("Registro");
    };


